const MAX_CIRCLES = 100;
const NUM_CIRCLES = 50;

var shaderCanvas, theShader;
var circles;
var colors, u_circles;

createOPC();
/**
Defines numOfCircles = NUM_CIRCLES
*/

function preload(){
	shaderCanvas = createGraphics(512, 512, WEBGL);
	let gl = shaderCanvas._renderer.GL;
	gl.enable(gl.BLEND);
	gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);

	theShader = new p5.Shader(shaderCanvas.renderer, vertShader, fragShader);
}

function setup() {
	createCanvas(shaderCanvas.width, shaderCanvas.height);
	background(0);
	createCirclePacking();
	setUniforms();
	redraw();	
}

var vectorDirections = [];
var angles = [];

function createCirclePacking(){
	vectorDirections = [];
	angles = [];
	while (vectorDirections.length<MAX_CIRCLES){
		var p = createVector(random(-1,1), random(-1,1), random(-1,1));
		p.normalize();

		var angleRadius = random(PI/8,PI/4);
		for (let i=0; i<vectorDirections.length; i++){
			var q = vectorDirections[i];
			var qAngle = angles[i];
			var d = acos(p.dot(q));
			angleRadius = min(angleRadius, d - qAngle);
		}

		if (angleRadius<0)
			continue;

		vectorDirections.push(p);
		angles.push(angleRadius);		
	}	

	colors = [];
	for (let i=0; i<MAX_CIRCLES; i++){
		colors.push(random(0.2,1));
		colors.push(random(0.2,1));
		colors.push(random(0.2,1));
	}
}


function rotateCircles(){
	u_circles = [];
	for (let i=0; i<vectorDirections.length; i++){
		var p = vectorDirections[i];
		var angle = angles[i];

		u_circles.push(cos(t)*p.x + sin(t)*p.z);
		u_circles.push(p.y);
		u_circles.push(-sin(t)*p.x + cos(t)*p.z);
		u_circles.push(1-cos(angle));
	}	
}


function setUniforms(){
	theShader.setUniform("u_resolution", [shaderCanvas.width, shaderCanvas.height]);
	theShader.setUniform("u_density", shaderCanvas.pixelDensity());
	theShader.setUniform("u_circles", u_circles);
	theShader.setUniform("u_colors", colors);
	theShader.setUniform("u_num_circles", numOfCircles);
	theShader.setUniform("u_time", t);

	shaderCanvas.shader(theShader);
	shaderCanvas.rect(0,0,width,height);
}

var t = 0;
var dt = 0.03;
var numFramesInGif = 60;
var gifFrames = 0;

function draw() {
	if (gifFrames == 0){
		t += (2*PI/10)*deltaTime/1000;
	} else {
		t += 2*PI / numFramesInGif;
		gifFrames -= 1;
	}
	rotateCircles();
	shaderCanvas.clear();	

	setUniforms();
	clear();
	image(shaderCanvas,0,0);
}

function createOPC(){
	OPC.slider('numOfCircles', NUM_CIRCLES);
	OPC.button('repackButton', 'Repack Circles');
	OPC.button('saveButton', 'Save image');
	//OPC.button('saveGifButton', 'Save gif');
}

var imageIndex = 0;
var gifIndex = 0;
function buttonPressed(variableName, value) {
	if (variableName === 'saveButton') {
		saveCanvas(shaderCanvas,`ball_${imageIndex}`,'png');
		imageIndex++;
	}
	if (variableName === 'saveGifButton') {
		gifFrames = numFramesInGif + 10;
		saveGif(`shader_ball_${gifIndex}`, numFramesInGif, {
			units: 'frames'
		});
		gifIndex++;
	}
	if (variableName === 'repackButton') {
		createCirclePacking(numOfCircles);
	}
}

// === Tab: vert ===
let vertShader = `

#ifdef GL_ES //for browser or mobile
//can change mediump to either lowp or highp.
precision mediump float;
#endif

// Input:
attribute vec3 aPosition;  //position of the vertex

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);

	// This is a weird behaviour in p5. Need to scale the vertices so they will appear in the right place.
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

	//Output:
  gl_Position = positionVec4;
}`;


// === Tab: frag ===
let fragShader = `
#ifdef GL_ES 
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_density;
uniform vec4 u_circles[${MAX_CIRCLES}];
uniform vec3 u_colors[${MAX_CIRCLES}];
uniform int u_num_circles;
uniform float u_time;


// ============================== Scene ==============================

vec3 random(float x){
	return vec3(
		fract(sin(x*123.123)*456.456),
		fract(sin(x*527.153)*938.938),
		fract(sin(x*189.521)*725.725)
		);
}


void main() {		
	vec2 uv = 2.*(gl_FragCoord.xy/u_density-u_resolution/2.)/u_resolution.y;
	float z = 1. - uv.x*uv.x - uv.y*uv.y;
	if (z>0.){
		z = sqrt(z);
		vec3 position = vec3(uv,z);
		vec3 color = vec3(1.,1.,1.); 
		float value = 0.;
		for (int i=0; i<${MAX_CIRCLES}; i++){
			if (i>=u_num_circles)
				break;
			value = dot(u_circles[i].xyz, position);
			float d = 1. - min( (1.-value)/u_circles[i].w , 1.0);
			color = mix(color, u_colors[i], sin(d*3.1415/2.) );
			//color = mix(color, u_colors[i], step(1.-value,u_circles[i].w));
			// which is the same as
			// if (1.-value<u_circles[i].w){
			// 	color = u_colors[i];
			// }
		}
		// Diffuse light
		float diffuse = max(dot(position,vec3(1.,1.,1.))/sqrt(3.),0.)*0.8+0.2;
		// Specular light
		vec3 lightSource = vec3(2.);
		vec3 normal = normalize(position);
		vec3 cameraPos = vec3(0.,0.,2.);
		vec3 reflectedLightDir = normalize(reflect(position-lightSource, normal));
		float specular = 1.0+pow(max(dot(reflectedLightDir, normalize(cameraPos-position)), 0.0),16.0)*0.2;
		gl_FragColor = vec4(specular*diffuse*color, 1.);
	} else {
		gl_FragColor = vec4(0., 0., 0., 0.); 
	}

}

`

